      want(event, "string", "event")
    end
    if type_of(handler) ~= "function" then
      want(handler, "function", "handler")
    end
    if options ~= nil then
      check_shape(options, "options", "EventOptions")
    end
    return hand.Player.on(self, event, handler, options)
  end

